"""
rag_core.py — Metadata-aware Retrieval-Augmented Generation core.

Self-contained (stdlib only) implementation of the retrieval half of a RAG
pipeline. It demonstrates, in one place:

  1. Metadata filtering   — narrow the candidate set *before* ranking using a
                            small filter DSL (and/or, eq/neq/in/contains,
                            gte/gt/lte/lt, exists, regex).
  2. Hybrid relevance     — BM25 (lexical/keyword) blended with TF-IDF cosine
                            similarity (dense-style term-vector ranking).
  3. Metadata boosts      — rank-time signals (source, recency, category, ...)
                            that re-rank documents after retrieval.
  4. MMR reranking        — Maximal Marginal Relevance for diversity when
                            several similar passages would otherwise crowd the
                            top-k.
  5. Grounded generation  — extractive, source-cited answers ([1], [2], ...)
                            with an "I don't have enough information" fallback.

The `MetadataAwareIndex` class is the seam where a real embedding model and a
vector database (Chroma / Pinecone / Weaviate / Qdrant / FAISS) can be plugged
in; every other component keeps the same interface.
"""

from __future__ import annotations

import math
import re
from dataclasses import dataclass, field
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple

# ---------------------------------------------------------------------------
# Text utilities
# ---------------------------------------------------------------------------

_TOKEN_RE = re.compile(r"[a-z0-9]+(?:['\-][a-z0-9]+)*")

_STOPWORDS = frozenset(
    """
    a an and are as at be but by for from had has have he her his if in into
    is it its may more no not of on or our she so some such than that the
    their them then there these they this those to was we were what when where
    which who will with would you your
    """.split()
)


def tokenize(text: str) -> List[str]:
    """Lower-cased alphanumeric tokens with stopwords removed."""
    return [t for t in _TOKEN_RE.findall(text.lower()) if t not in _STOPWORDS]


def split_sentences(text: str) -> List[str]:
    """Naive sentence splitter used for extractive answer generation."""
    parts = re.split(r"(?<=[.!?])\s+", text.strip())
    return [p for p in parts if p]


# ---------------------------------------------------------------------------
# Document model
# ---------------------------------------------------------------------------


@dataclass
class Document:
    """A retrievable chunk plus the metadata used for filtering and boosting.

    Example metadata keys used throughout the sample corpus::

        category (str), source (str), year (int), author (str),
        tags (list[str]), importance (float), access_level (str)
    """

    doc_id: str
    title: str
    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)

    @property
    def searchable_text(self) -> str:
        return f"{self.title} {self.text}"


# ---------------------------------------------------------------------------
# Metadata filtering
# ---------------------------------------------------------------------------

_OPERATORS = {
    "eq", "neq", "in", "contains", "exists", "gte", "gt", "lte", "lt", "regex",
}


def _apply_op(value: Any, op: str, expected: Any) -> bool:
    """Apply one operator to a metadata value."""
    if op == "eq":
        return value == expected
    if op == "neq":
        return value != expected
    if op == "in":
        try:
            return value in expected
        except TypeError:
            return False
    if op == "contains":
        try:
            return expected in value
        except TypeError:
            return False
    if op == "exists":
        return (value is not None) == bool(expected)
    if op in ("gte", "gt", "lte", "lt"):
        try:
            return {
                "gte": lambda: value >= expected,
                "gt": lambda: value > expected,
                "lte": lambda: value <= expected,
                "lt": lambda: value < expected,
            }[op]()
        except TypeError:
            return False
    if op == "regex":
        try:
            return re.search(expected, str(value)) is not None
        except re.error:
            return False
    raise ValueError(f"unknown metadata operator: {op!r}")


def matches_metadata(metadata: Dict[str, Any], spec: Optional[Any]) -> bool:
    """Evaluate a metadata filter spec against a document's metadata.

    Spec grammar (all conditions combine with AND unless 'or' is used)::

        None                                  -> matches everything
        [spec, spec, ...]                     -> AND of each spec
        {"and": [spec, ...]}                  -> AND
        {"or": [spec, ...]}                   -> OR
        {"field": expected_value}             -> equality
        {"field": {"eq": v, "gte": v, ...}}   -> operator conditions (AND)

    Example::

        {
            "or": [
                {"category": "ml"},
                {"tags": {"contains": "gpu"}},
            ],
            "year": {"gte": 2021},
        }
    """
    if spec is None:
        return True
    if isinstance(spec, list):
        return all(matches_metadata(metadata, s) for s in spec)
    if isinstance(spec, dict):
        if "and" in spec:
            return all(matches_metadata(metadata, s) for s in spec["and"])
        if "or" in spec:
            return any(matches_metadata(metadata, s) for s in spec["or"])
        for field_name, cond in spec.items():
            if isinstance(cond, dict) and cond and all(k in _OPERATORS for k in cond):
                for op, expected in cond.items():
                    if not _apply_op(metadata.get(field_name), op, expected):
                        return False
            else:
                if not _apply_op(metadata.get(field_name), "eq", cond):
                    return False
        return True
    raise ValueError("invalid metadata filter spec: expected dict or list")


def score_metadata_boost(
    metadata: Dict[str, Any], rules: Optional[Sequence[Dict[str, Any]]]
) -> float:
    """Sum of weights for every boost rule matched by the metadata.

    Rule shape::

        {"field": "source", "op": "eq", "value": "arxiv", "weight": 1.5}
        {"field": "year",   "op": "gte", "value": 2022, "weight": 0.5}
    """
    if not rules:
        return 0.0
    total = 0.0
    for rule in rules:
        field_name = rule.get("field")
        op = rule.get("op", "eq")
        value = rule.get("value")
        weight = rule.get("weight", 1.0)
        if _apply_op(metadata.get(field_name), op, value):
            total += weight
    return total


# ---------------------------------------------------------------------------
# BM25 (lexical ranking)
# ---------------------------------------------------------------------------


class BM25:
    """Okapi BM25 over pre-tokenized documents."""

    def __init__(
        self,
        corpus_terms: Sequence[Sequence[str]],
        k1: float = 1.5,
        b: float = 0.75,
    ) -> None:
        self.k1 = k1
        self.b = b
        self.doc_terms = [list(t) for t in corpus_terms]
        self.n_docs = len(self.doc_terms)
        self.avgdl = sum(len(d) for d in self.doc_terms) / max(1, self.n_docs)
        doc_freq: Dict[str, int] = {}
        for terms in self.doc_terms:
            for t in set(terms):
                doc_freq[t] = doc_freq.get(t, 0) + 1
        self.doc_freq = doc_freq
        self.idf = {
            t: math.log(1 + (self.n_docs - f + 0.5) / (f + 0.5))
            for t, f in doc_freq.items()
        }

    def score(self, query_terms: Sequence[str], doc_idx: int) -> float:
        if not query_terms:
            return 0.0
        terms = self.doc_terms[doc_idx]
        dl = len(terms)
        tf_counts: Dict[str, int] = {}
        for t in terms:
            tf_counts[t] = tf_counts.get(t, 0) + 1
        total = 0.0
        for t in set(query_terms):
            idf = self.idf.get(t)
            if idf is None:
                continue
            tf = tf_counts.get(t, 0)
            if tf == 0:
                continue
            denom = tf + self.k1 * (1 - self.b + self.b * dl / self.avgdl)
            total += idf * (tf * (self.k1 + 1)) / denom
        return total


# ---------------------------------------------------------------------------
# TF-IDF vectors + cosine similarity (dense-style ranking)
# ---------------------------------------------------------------------------


def _tfidf_vector(terms: Sequence[str], idf: Dict[str, float]) -> Dict[str, float]:
    tf_counts: Dict[str, float] = {}
    for t in terms:
        tf_counts[t] = tf_counts.get(t, 0) + 1.0
    vec: Dict[str, float] = {}
    n = len(terms)
    for t, tf in tf_counts.items():
        w = idf.get(t, 0.0)
        if w:
            vec[t] = (tf / n) * w
    norm = math.sqrt(sum(x * x for x in vec.values()))
    if norm:
        return {t: x / norm for t, x in vec.items()}
    return vec


def build_tfidf(
    corpus_terms: Sequence[Sequence[str]],
) -> Tuple[List[Dict[str, float]], Dict[str, float]]:
    """Return (per-document L2-normalized TF-IDF vectors, idf table)."""
    n_docs = len(corpus_terms)
    doc_freq: Dict[str, int] = {}
    for terms in corpus_terms:
        for t in set(terms):
            doc_freq[t] = doc_freq.get(t, 0) + 1
    idf = {t: math.log(n_docs / (1 + f)) + 1.0 for t, f in doc_freq.items()}
    return [_tfidf_vector(terms, idf) for terms in corpus_terms], idf


def cosine(vec_a: Dict[str, float], vec_b: Dict[str, float]) -> float:
    """Cosine similarity between (L2-normalized) sparse vectors."""
    if not vec_a or not vec_b:
        return 0.0
    if len(vec_a) > len(vec_b):
        vec_a, vec_b = vec_b, vec_a  # iterate over the smaller vector
    return sum(x * vec_b.get(t, 0.0) for t, x in vec_a.items())


# ---------------------------------------------------------------------------
# Index + search
# ---------------------------------------------------------------------------

DEFAULT_WEIGHTS = {"bm25": 0.6, "cosine": 0.4, "boost": 1.0}


@dataclass
class RankedResult:
    document: Document
    index: int
    bm25: float
    cosine: float
    boost: float
    score: float
    rank: int = 0

    @property
    def doc_id(self) -> str:
        return self.document.doc_id

    @property
    def title(self) -> str:
        return self.document.title


class MetadataAwareIndex:
    """In-memory index mapping Document -> BM25 + TF-IDF structures.

    This is the swap point for a real vector database: replace the internal
    structures with Chroma/Pinecone/Weaviate/Qdrant/FAISS calls that persist
    metadata alongside embeddings, keeping the same `search` signature.
    """

    def __init__(
        self,
        documents: Sequence[Document],
        k1: float = 1.5,
        b: float = 0.75,
    ) -> None:
        self.documents = list(documents)
        self.corpus_terms = [tokenize(d.searchable_text) for d in self.documents]
        self.bm25 = BM25(self.corpus_terms, k1=k1, b=b)
        self.tfidf_vectors, self.idf = build_tfidf(self.corpus_terms)

    # -- metadata helpers ----------------------------------------------------

    def filter_documents(self, metadata_filter: Any) -> List[int]:
        """Indices of documents matching the metadata filter (for auditing)."""
        return [
            i
            for i, doc in enumerate(self.documents)
            if matches_metadata(doc.metadata, metadata_filter)
        ]

    # -- search ---------------------------------------------------------------

    def search(
        self,
        query: str,
        *,
        metadata_filter: Optional[Any] = None,
        boost_rules: Optional[Sequence[Dict[str, Any]]] = None,
        k: int = 5,
        weights: Optional[Dict[str, float]] = None,
        use_mmr: bool = False,
        lambda_mult: float = 0.7,
        fetch_k: Optional[int] = None,
    ) -> List[RankedResult]:
        """Retrieve + rank documents for `query`.

        Pipeline: metadata filter -> per-document BM25 & cosine scores ->
        min-max normalization -> weighted blend -> metadata boost ->
        (optional) MMR diversity reranking -> top-k.
        """
        q_terms = tokenize(query)
        q_vec = _tfidf_vector(q_terms, self.idf)
        weights = dict(DEFAULT_WEIGHTS if weights is None else weights)

        raw: List[Dict[str, Any]] = []
        for i, doc in enumerate(self.documents):
            if metadata_filter is not None and not matches_metadata(doc.metadata, metadata_filter):
                continue
            raw.append(
                {
                    "doc": doc,
                    "i": i,
                    "bm25": self.bm25.score(q_terms, i),
                    "cosine": cosine(self.tfidf_vectors[i], q_vec),
                    "boost": score_metadata_boost(doc.metadata, boost_rules),
                }
            )

        if not raw:
            return []

        def _norm(attr: str) -> List[float]:
            vals = [r[attr] for r in raw]
            lo, hi = min(vals), max(vals)
            span = hi - lo
            if span <= 1e-12:
                return [1.0 if hi > 0 else 0.0] * len(vals)
            return [(v - lo) / span for v in vals]

        bm_norm = _norm("bm25")
        cos_norm = _norm("cosine")
        boost_vals = [r["boost"] for r in raw]
        b_lo, b_hi = min(boost_vals), max(boost_vals)

        results: List[RankedResult] = []
        for idx, r in enumerate(raw):
            score = weights.get("bm25", 0.0) * bm_norm[idx] + weights.get(
                "cosine", 0.0
            ) * cos_norm[idx]
            if b_hi - b_lo > 1e-12:
                norm_boost = (r["boost"] - b_lo) / (b_hi - b_lo)
            else:
                norm_boost = 1.0 if r["boost"] > 0 else 0.0
            score += weights.get("boost", 1.0) * norm_boost
            results.append(
                RankedResult(
                    document=r["doc"],
                    index=r["i"],
                    bm25=r["bm25"],
                    cosine=r["cosine"],
                    boost=r["boost"],
                    score=score,
                )
            )

        results.sort(key=lambda r: r.score, reverse=True)

        if use_mmr and len(results) > k:
            fetch = fetch_k if fetch_k is not None else max(k * 3, 10)
            results = mmr_select(results[:fetch], q_vec, self.tfidf_vectors, k, lambda_mult)

        for rank, r in enumerate(results, start=1):
            r.rank = rank
        return results[:k]


def mmr_select(
    candidates: Sequence[RankedResult],
    q_vec: Dict[str, float],
    doc_vectors: Sequence[Dict[str, float]],
    k: int,
    lambda_mult: float,
) -> List[RankedResult]:
    """Maximal Marginal Relevance: trade relevance against redundancy.

    mmr = lambda * relevance - (1 - lambda) * max_similarity_to_selected
    """
    selected: List[RankedResult] = []
    remaining = list(candidates)
    while len(selected) < k and remaining:
        best_idx: Optional[int] = None
        best_mmr = -math.inf
        for idx, cand in enumerate(remaining):
            rel = cand.score
            sim_to_selected = (
                max(
                    cosine(doc_vectors[cand.index], doc_vectors[s.index])
                    for s in selected
                )
                if selected
                else 0.0
            )
            mmr = lambda_mult * rel - (1.0 - lambda_mult) * sim_to_selected
            if mmr > best_mmr:
                best_mmr = mmr
                best_idx = idx
        selected.append(remaining.pop(best_idx))  # type: ignore[arg-type]
    return selected


# ---------------------------------------------------------------------------
# Grounded generation
# ---------------------------------------------------------------------------


def extract_answer(
    query: str,
    ranked: Sequence[RankedResult],
    max_sentences: int = 3,
    min_confidence: float = 0.05,
) -> Tuple[str, List[Document]]:
    """Extractive, citation-grounded answer built from the top-ranked docs.

    Returns "(answer_text, source_documents)". Answers quote the most
    overlapping sentence from each retrieved source with a [n] citation, and
    fall back to an explicit "not enough information" response when the top
    result is below `min_confidence` (i.e. no lexical/vector overlap).
    """
    if not ranked or ranked[0].score < min_confidence:
        return "I don't have enough information to answer this question.", []

    q_terms = set(tokenize(query))
    selected: List[Tuple[str, int]] = []
    sources: List[Document] = []
    for rr in ranked:
        if len(selected) >= max_sentences:
            break
        doc = rr.document
        ref = len(sources) + 1
        sources.append(doc)
        for sent in split_sentences(doc.text):
            if q_terms & set(tokenize(sent)):
                selected.append((sent.rstrip(), ref))
                break
        if not any(ref == r for _, r in selected):
            sents = split_sentences(doc.text)
            if sents:
                selected.append((sents[0].rstrip(), ref))

    answer = " ".join(f'"{sent}" [{ref}]' for sent, ref in selected)
    return answer, sources


@dataclass
class RagResponse:
    query: str
    answer: str
    sources: List[Document]
    ranked: List[RankedResult]


def run_rag_pipeline(
    index: MetadataAwareIndex,
    query: str,
    *,
    metadata_filter: Optional[Any] = None,
    boost_rules: Optional[Sequence[Dict[str, Any]]] = None,
    k: int = 5,
    use_mmr: bool = False,
    lambda_mult: float = 0.7,
    fetch_k: Optional[int] = None,
    weights: Optional[Dict[str, float]] = None,
    max_sentences: int = 3,
    min_confidence: float = 0.05,
) -> RagResponse:
    """End-to-end RAG call: filter -> rank -> rerank -> grounded answer."""
    ranked = index.search(
        query,
        metadata_filter=metadata_filter,
        boost_rules=boost_rules,
        k=k,
        weights=weights,
        use_mmr=use_mmr,
        lambda_mult=lambda_mult,
        fetch_k=fetch_k,
    )
    answer, sources = extract_answer(
        query, ranked, max_sentences=max_sentences, min_confidence=min_confidence
    )
    return RagResponse(query=query, answer=answer, sources=sources, ranked=ranked)

"""
rag_core.py — Metadata-aware Retrieval-Augmented Generation core.

Self-contained (stdlib only) implementation of the retrieval half of a RAG
pipeline. It demonstrates, in one place:

  1. Metadata filtering   — narrow the candidate set *before* ranking using a
                            small filter DSL (and/or, eq/neq/in/contains,
                            gte/gt/lte/lt, exists, regex).
  2. Hybrid relevance     — BM25 (lexical/keyword) blended with TF-IDF cosine
                            similarity (dense-style term-vector ranking).
  3. Metadata boosts      — rank-time signals (source, recency, category, ...)
                            that re-rank documents after retrieval.
  4. MMR reranking        — Maximal Marginal Relevance for diversity when
                            several similar passages would otherwise crowd the
                            top-k.
  5. Grounded generation  — extractive, source-cited answers ([1], [2], ...)
                            with an "I don't have enough information" fallback.

The `MetadataAwareIndex` class is the seam where a real embedding model and a
vector database (Chroma / Pinecone / Weaviate / Qdrant / FAISS) can be plugged
in; every other component keeps the same interface.
"""

from __future__ import annotations

import math
import re
from dataclasses import dataclass, field
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple

# ---------------------------------------------------------------------------
# Text utilities
# ---------------------------------------------------------------------------

_TOKEN_RE = re.compile(r"[a-z0-9]+(?:['\-][a-z0-9]+)*")

_STOPWORDS = frozenset(
    """
    a an and are as at be but by for from had has have he her his if in into
    is it its may more no not of on or our she so some such than that the
    their them then there these they this those to was we were what when where
    which who will with would you your
    """.split()
)


def tokenize(text: str) -> List[str]:
    """Lower-cased alphanumeric tokens with stopwords removed."""
    return [t for t in _TOKEN_RE.findall(text.lower()) if t not in _STOPWORDS]


def split_sentences(text: str) -> List[str]:
    """Naive sentence splitter used for extractive answer generation."""
    parts = re.split(r"(?<=[.!?])\s+", text.strip())
    return [p for p in parts if p]


# ---------------------------------------------------------------------------
# Document model
# ---------------------------------------------------------------------------


@dataclass
class Document:
    """A retrievable chunk plus the metadata used for filtering and boosting.

    Example metadata keys used throughout the sample corpus::

        category (str), source (str), year (int), author (str),
        tags (list[str]), importance (float), access_level (str)
    """

    doc_id: str
    title: str
    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)

    @property
    def searchable_text(self) -> str:
        return f"{self.title} {self.text}"


# ---------------------------------------------------------------------------
# Metadata filtering
# ---------------------------------------------------------------------------

_OPERATORS = {
    "eq", "neq", "in", "contains", "exists", "gte", "gt", "lte", "lt", "regex",
}


def _apply_op(value: Any, op: str, expected: Any) -> bool:
    """Apply one operator to a metadata value."""
    if op == "eq":
        return value == expected
    if op == "neq":
        return value != expected
    if op == "in":
        try:
            return value in expected
        except TypeError:
            return False
    if op == "contains":
        try:
            return expected in value
        except TypeError:
            return False
    if op == "exists":
        return (value is not None) == bool(expected)
    if op in ("gte", "gt", "lte", "lt"):
        try:
            return {
                "gte": lambda: value >= expected,
                "gt": lambda: value > expected,
                "lte": lambda: value <= expected,
                "lt": lambda: value < expected,
            }[op]()
        except TypeError:
            return False
    if op == "regex":
        try:
            return re.search(expected, str(value)) is not None
        except re.error:
            return False
    raise ValueError(f"unknown metadata operator: {op!r}")


def matches_metadata(metadata: Dict[str, Any], spec: Optional[Any]) -> bool:
    """Evaluate a metadata filter spec against a document's metadata.

    Spec grammar (all conditions combine with AND unless 'or' is used)::

        None                                  -> matches everything
        [spec, spec, ...]                     -> AND of each spec
        {"and": [spec, ...]}                  -> AND
        {"or": [spec, ...]}                   -> OR
        {"field": expected_value}             -> equality
        {"field": {"eq": v, "gte": v, ...}}   -> operator conditions (AND)

    Example::

        {
            "or": [
                {"category": "ml"},
                {"tags": {"contains": "gpu"}},
            ],
            "year": {"gte": 2021},
        }
    """
    if spec is None:
        return True
    if isinstance(spec, list):
        return all(matches_metadata(metadata, s) for s in spec)
    if isinstance(spec, dict):
        if "and" in spec:
            return all(matches_metadata(metadata, s) for s in spec["and"])
        if "or" in spec:
            return any(matches_metadata(metadata, s) for s in spec["or"])
        for field_name, cond in spec.items():
            if isinstance(cond, dict) and cond and all(k in _OPERATORS for k in cond):
                for op, expected in cond.items():
                    if not _apply_op(metadata.get(field_name), op, expected):
                        return False
            else:
                if not _apply_op(metadata.get(field_name), "eq", cond):
                    return False
        return True
    raise ValueError("invalid metadata filter spec: expected dict or list")


def score_metadata_boost(
    metadata: Dict[str, Any], rules: Optional[Sequence[Dict[str, Any]]]
) -> float:
    """Sum of weights for every boost rule matched by the metadata.

    Rule shape::

        {"field": "source", "op": "eq", "value": "arxiv", "weight": 1.5}
        {"field": "year",   "op": "gte", "value": 2022, "weight": 0.5}
    """
    if not rules:
        return 0.0
    total = 0.0
    for rule in rules:
        field_name = rule.get("field")
        op = rule.get("op", "eq")
        value = rule.get("value")
        weight = rule.get("weight", 1.0)
        if _apply_op(metadata.get(field_name), op, value):
            total += weight
    return total


# ---------------------------------------------------------------------------
# BM25 (lexical ranking)
# ---------------------------------------------------------------------------


class BM25:
    """Okapi BM25 over pre-tokenized documents."""

    def __init__(
        self,
        corpus_terms: Sequence[Sequence[str]],
        k1: float = 1.5,
        b: float = 0.75,
    ) -> None:
        self.k1 = k1
        self.b = b
        self.doc_terms = [list(t) for t in corpus_terms]
        self.n_docs = len(self.doc_terms)
        self.avgdl = sum(len(d) for d in self.doc_terms) / max(1, self.n_docs)
        doc_freq: Dict[str, int] = {}
        for terms in self.doc_terms:
            for t in set(terms):
                doc_freq[t] = doc_freq.get(t, 0) + 1
        self.doc_freq = doc_freq
        self.idf = {
            t: math.log(1 + (self.n_docs - f + 0.5) / (f + 0.5))
            for t, f in doc_freq.items()
        }

    def score(self, query_terms: Sequence[str], doc_idx: int) -> float:
        if not query_terms:
            return 0.0
        terms = self.doc_terms[doc_idx]
        dl = len(terms)
        tf_counts: Dict[str, int] = {}
        for t in terms:
            tf_counts[t] = tf_counts.get(t, 0) + 1
        total = 0.0
        for t in set(query_terms):
            idf = self.idf.get(t)
            if idf is None:
                continue
            tf = tf_counts.get(t, 0)
            if tf == 0:
                continue
            denom = tf + self.k1 * (1 - self.b + self.b * dl / self.avgdl)
            total += idf * (tf * (self.k1 + 1)) / denom
        return total


# ---------------------------------------------------------------------------
# TF-IDF vectors + cosine similarity (dense-style ranking)
# ---------------------------------------------------------------------------


def _tfidf_vector(terms: Sequence[str], idf: Dict[str, float]) -> Dict[str, float]:
    tf_counts: Dict[str, float] = {}
    for t in terms:
        tf_counts[t] = tf_counts.get(t, 0) + 1.0
    vec: Dict[str, float] = {}
    n = len(terms)
    for t, tf in tf_counts.items():
        w = idf.get(t, 0.0)
        if w:
            vec[t] = (tf / n) * w
    norm = math.sqrt(sum(x * x for x in vec.values()))
    if norm:
        return {t: x / norm for t, x in vec.items()}
    return vec


def build_tfidf(
    corpus_terms: Sequence[Sequence[str]],
) -> Tuple[List[Dict[str, float]], Dict[str, float]]:
    """Return (per-document L2-normalized TF-IDF vectors, idf table)."""
    n_docs = len(corpus_terms)
    doc_freq: Dict[str, int] = {}
    for terms in corpus_terms:
        for t in set(terms):
            doc_freq[t] = doc_freq.get(t, 0) + 1
    idf = {t: math.log(n_docs / (1 + f)) + 1.0 for t, f in doc_freq.items()}
    return [_tfidf_vector(terms, idf) for terms in corpus_terms], idf


def cosine(vec_a: Dict[str, float], vec_b: Dict[str, float]) -> float:
    """Cosine similarity between (L2-normalized) sparse vectors."""
    if not vec_a or not vec_b:
        return 0.0
    if len(vec_a) > len(vec_b):
        vec_a, vec_b = vec_b, vec_a  # iterate over the smaller vector
    return sum(x * vec_b.get(t, 0.0) for t, x in vec_a.items())


# ---------------------------------------------------------------------------
# Index + search
# ---------------------------------------------------------------------------

DEFAULT_WEIGHTS = {"bm25": 0.6, "cosine": 0.4, "boost": 1.0}


@dataclass
class RankedResult:
    document: Document
    index: int
    bm25: float
    cosine: float
    boost: float
    score: float
    rank: int = 0

    @property
    def doc_id(self) -> str:
        return self.document.doc_id

    @property
    def title(self) -> str:
        return self.document.title


class MetadataAwareIndex:
    """In-memory index mapping Document -> BM25 + TF-IDF structures.

    This is the swap point for a real vector database: replace the internal
    structures with Chroma/Pinecone/Weaviate/Qdrant/FAISS calls that persist
    metadata alongside embeddings, keeping the same `search` signature.
    """

    def __init__(
        self,
        documents: Sequence[Document],
        k1: float = 1.5,
        b: float = 0.75,
    ) -> None:
        self.documents = list(documents)
        self.corpus_terms = [tokenize(d.searchable_text) for d in self.documents]
        self.bm25 = BM25(self.corpus_terms, k1=k1, b=b)
        self.tfidf_vectors, self.idf = build_tfidf(self.corpus_terms)

    # -- metadata helpers ----------------------------------------------------

    def filter_documents(self, metadata_filter: Any) -> List[int]:
        """Indices of documents matching the metadata filter (for auditing)."""
        return [
            i
            for i, doc in enumerate(self.documents)
            if matches_metadata(doc.metadata, metadata_filter)
        ]

    # -- search ---------------------------------------------------------------

    def search(
        self,
        query: str,
        *,
        metadata_filter: Optional[Any] = None,
        boost_rules: Optional[Sequence[Dict[str, Any]]] = None,
        k: int = 5,
        weights: Optional[Dict[str, float]] = None,
        use_mmr: bool = False,
        lambda_mult: float = 0.7,
        fetch_k: Optional[int] = None,
    ) -> List[RankedResult]:
        """Retrieve + rank documents for `query`.

        Pipeline: metadata filter -> per-document BM25 & cosine scores ->
        min-max normalization -> weighted blend -> metadata boost ->
        (optional) MMR diversity reranking -> top-k.
        """
        q_terms = tokenize(query)
        q_vec = _tfidf_vector(q_terms, self.idf)
        weights = dict(DEFAULT_WEIGHTS if weights is None else weights)

        raw: List[Dict[str, Any]] = []
        for i, doc in enumerate(self.documents):
            if metadata_filter is not None and not matches_metadata(doc.metadata, metadata_filter):
                continue
            raw.append(
                {
                    "doc": doc,
                    "i": i,
                    "bm25": self.bm25.score(q_terms, i),
                    "cosine": cosine(self.tfidf_vectors[i], q_vec),
                    "boost": score_metadata_boost(doc.metadata, boost_rules),
                }
            )

        if not raw:
            return []

        def _norm(attr: str) -> List[float]:
            vals = [r[attr] for r in raw]
            lo, hi = min(vals), max(vals)
            span = hi - lo
            if span <= 1e-12:
                return [1.0 if hi > 0 else 0.0] * len(vals)
            return [(v - lo) / span for v in vals]

        bm_norm = _norm("bm25")
        cos_norm = _norm("cosine")
        boost_vals = [r["boost"] for r in raw]
        b_lo, b_hi = min(boost_vals), max(boost_vals)

        results: List[RankedResult] = []
        for idx, r in enumerate(raw):
            score = weights.get("bm25", 0.0) * bm_norm[idx] + weights.get(
                "cosine", 0.0
            ) * cos_norm[idx]
            if b_hi - b_lo > 1e-12:
                norm_boost = (r["boost"] - b_lo) / (b_hi - b_lo)
            else:
                norm_boost = 1.0 if r["boost"] > 0 else 0.0
            score += weights.get("boost", 1.0) * norm_boost
            results.append(
                RankedResult(
                    document=r["doc"],
                    index=r["i"],
                    bm25=r["bm25"],
                    cosine=r["cosine"],
                    boost=r["boost"],
                    score=score,
                )
            )

        results.sort(key=lambda r: r.score, reverse=True)

        if use_mmr and len(results) > k:
            fetch = fetch_k if fetch_k is not None else max(k * 3, 10)
            results = mmr_select(results[:fetch], q_vec, self.tfidf_vectors, k, lambda_mult)

        for rank, r in enumerate(results, start=1):
            r.rank = rank
        return results[:k]


def mmr_select(
    candidates: Sequence[RankedResult],
    q_vec: Dict[str, float],
    doc_vectors: Sequence[Dict[str, float]],
    k: int,
    lambda_mult: float,
) -> List[RankedResult]:
    """Maximal Marginal Relevance: trade relevance against redundancy.

    mmr = lambda * relevance - (1 - lambda) * max_similarity_to_selected
    """
    selected: List[RankedResult] = []
    remaining = list(candidates)
    while len(selected) < k and remaining:
        best_idx: Optional[int] = None
        best_mmr = -math.inf
        for idx, cand in enumerate(remaining):
            rel = cand.score
            sim_to_selected = (
                max(
                    cosine(doc_vectors[cand.index], doc_vectors[s.index])
                    for s in selected
                )
                if selected
                else 0.0
            )
            mmr = lambda_mult * rel - (1.0 - lambda_mult) * sim_to_selected
            if mmr > best_mmr:
                best_mmr = mmr
                best_idx = idx
        selected.append(remaining.pop(best_idx))  # type: ignore[arg-type]
    return selected


# ---------------------------------------------------------------------------
# Grounded generation
# ---------------------------------------------------------------------------


def extract_answer(
    query: str,
    ranked: Sequence[RankedResult],
    max_sentences: int = 3,
    min_confidence: float = 0.05,
) -> Tuple[str, List[Document]]:
    """Extractive, citation-grounded answer built from the top-ranked docs.

    Returns "(answer_text, source_documents)". Answers quote the most
    overlapping sentence from each retrieved source with a [n] citation, and
    fall back to an explicit "not enough information" response when the top
    result is below `min_confidence` (i.e. no lexical/vector overlap).
    """
    if not ranked or ranked[0].score < min_confidence:
        return "I don't have enough information to answer this question.", []

    q_terms = set(tokenize(query))
    selected: List[Tuple[str, int]] = []
    sources: List[Document] = []
    for rr in ranked:
        if len(selected) >= max_sentences:
            break
        doc = rr.document
        ref = len(sources) + 1
        sources.append(doc)
        for sent in split_sentences(doc.text):
            if q_terms & set(tokenize(sent)):
                selected.append((sent.rstrip(), ref))
                break
        if not any(ref == r for _, r in selected):
            sents = split_sentences(doc.text)
            if sents:
                selected.append((sents[0].rstrip(), ref))

    answer = " ".join(f'"{sent}" [{ref}]' for sent, ref in selected)
    return answer, sources


@dataclass
class RagResponse:
    query: str
    answer: str
    sources: List[Document]
    ranked: List[RankedResult]


def run_rag_pipeline(
    index: MetadataAwareIndex,
    query: str,
    *,
    metadata_filter: Optional[Any] = None,
    boost_rules: Optional[Sequence[Dict[str, Any]]] = None,
    k: int = 5,
    use_mmr: bool = False,
    lambda_mult: float = 0.7,
    fetch_k: Optional[int] = None,
    weights: Optional[Dict[str, float]] = None,
    max_sentences: int = 3,
    min_confidence: float = 0.05,
) -> RagResponse:
    """End-to-end RAG call: filter -> rank -> rerank -> grounded answer."""
    ranked = index.search(
        query,
        metadata_filter=metadata_filter,
        boost_rules=boost_rules,
        k=k,
        weights=weights,
        use_mmr=use_mmr,
        lambda_mult=lambda_mult,
        fetch_k=fetch_k,
    )
    answer, sources = extract_answer(
        query, ranked, max_sentences=max_sentences, min_confidence=min_confidence
    )
    return RagResponse(query=query, answer=answer, sources=sources, ranked=ranked)
